def row(raw,f):
 slot=raw['slot'];ph=raw.get('phases',{}).get('measurement',{});records=ph.get('request_records',[]);mapping=raw['replica_to_family'];target=slot['target_task'];g=slot['Generalist'];s=slot['Specialist'];factor=read(OUT/'existing_empirical_catalog.json')['safe_factor'];n=Counter(mapping[r['model']] for r in records if r['task']==target);nc=Counter(mapping[r['model']] for r in records if r['task']==target and r['status']=='completed');N=sum(n.values());bg=Counter(mapping[r['model']] for r in records if r['task']=='visual_qa' and r['status']=='completed')
 idle=statistics.mean(v['owned_used_mib'] for v in raw['postwarm_idle']) if raw.get('postwarm_idle') else None;after=statistics.mean(v['owned_used_mib'] for v in raw['postmeasurement_idle']) if raw.get('postmeasurement_idle') else None;peak=max((v['owned_used_mib'] for v in raw['telemetry']['samples']),default=None);memfit=all(v is not None and factor*v<=slot['safe_memory_budget_mib']+1e-6 for v in [idle,after]) and peak is not None and peak<=slot['safe_memory_budget_mib']+1e-6
 realG=n.get(g,0)/N if N else None;realS=n.get(s,0)/N if N else None;condition=(slot['deployment']=={g:1} and nc.get(g,0)>0 and nc.get(s,0)==0) if slot['stage']=='LOW' else (slot['deployment']=={g:1,s:1} and realS is not None and realS>=.8) if slot['stage']=='MID' else (slot['deployment']=={g:1,s:1} and nc.get(g,0)>0 and nc.get(s,0)>0)
 stability=ph.get('stability',{}).get('stability_state_v2');metrics=ph.get('metrics',{});passed=bool(raw['valid_session'] and stability=='steady' and memfit and condition and bg.get(g,0)>0)
 target_metrics=ph.get('per_task_metrics',{}).get(target,{});background_metrics=ph.get('per_task_metrics',{}).get('visual_qa',{})
 return {**slot,'valid_session':raw['valid_session'],'observed_worker_count':len(raw['worker_identities']),'observed_worker_PIDs':{k:v['pid'] for k,v in raw['worker_identities'].items()},'observed_target_offered_counts':dict(n),'observed_target_completed_counts':dict(nc),'actual_target_G_fraction':realG,'actual_target_S_fraction':realS,'observed_background_completed_counts':dict(bg),'mean_E2E_ms':metrics.get('mean_e2e_ms'),'pooled_P95_E2E_ms':metrics.get('p95_e2e_ms'),'target_mean_E2E_ms':target_metrics.get('mean_e2e_latency_ms'),'target_P95_E2E_ms':target_metrics.get('p95_e2e_latency_ms'),'background_mean_E2E_ms':background_metrics.get('mean_e2e_latency_ms'),'background_P95_E2E_ms':background_metrics.get('p95_e2e_latency_ms'),'per_task_metrics':ph.get('per_task_metrics',{}),'completion_ratio':metrics.get('completion_ratio'),'throughput_rps':metrics.get('completed_throughput_rps'),'within_window_completion_ratio':metrics.get('within_window_completion_ratio'),'postwarm_idle_GPU_mib':idle,'postmeasurement_idle_GPU_mib':after,'postwarm_safe_memory_mib':factor*idle if idle is not None else None,'postmeasurement_safe_memory_mib':factor*after if after is not None else None,'sampled_peak_owned_GPU_mib':peak,'safe_memory_budget_passed':memfit,'stability':stability,'stability_detail':ph.get('stability'),'stability_evidence':{k:v for k,v in ph.get('stability_evidence',{}).items() if k not in ['backlog_timeline','queue_wait_values_ms','offered_backlog_diagnostic']},'phase_deployment_and_real_routing_condition_passed':condition,'phase_passed':passed,'errors':raw['errors'],'GPU_release_verified':raw['gpu_release']['verified'],'raw':ref(OUT/'raw_runs'/(slot['run_id']+'.json'))}

