 f=read(OUT/'gpu_validation_freeze.json');verify(f['implementation']+[f['witness'],f['search_policy'],f['catalog']]);rows=[row(read(OUT/'raw_runs'/(s['run_id']+'.json')),f) for s in f['slots']];assert len(rows)==9;save('gpu_validation_rows.json',rows);csvsave('gpu_validation_measurements.csv',rows)
